RSpec.describe Timekeeping::ReservationClient do
  # "It uses a service identity, not a user token."
  # "Build the path from the request's stored company_id."
  it "reservation client signs every call with a service token bound to the request company and only that route's operation" do
    company_id = 4321
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    http = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    minted_for = []
    credential = lambda do |company_id:, operation:|
      minted_for << [company_id, operation]
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    client = described_class.new(http:, credential:)
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 55, operation_id: SecureRandom.uuid,
      generation: fake.generation, disposition: "active", entries: []
    )

    expect(client.prepare(request).state).to eq("prepared")
    expect(client.commit(request).state).to eq("committed")

    expect(minted_for.map(&:first).uniq).to eq([company_id])
    route_operations = {
      "/v1/companies/#{company_id}/reservations/prepare" => "reservations.prepare",
      "/v1/companies/#{company_id}/reservations/commit" => "reservations.commit"
    }
    expect(fake.requests.pluck(:path)).to all(satisfy { |path| route_operations.key?(path) })
    fake.requests.each do |sent|
      authorization = sent[:headers].find { |name, _value| name.to_s.casecmp?("authorization") }&.last.to_s
      expect(authorization).to start_with("Bearer ")
      payload, = JWT.decode(authorization.delete_prefix("Bearer "), timekeeping_key_pair.public_key, true, algorithm: "RS256")
      expect(payload["typ"]).to eq("timekeeping_service")
      expect(payload["company_id"]).to eq(company_id)
      expect(payload["operations"]).to eq([route_operations.fetch(sent[:path])])
    end
  end
end

RSpec.describe Timekeeping::ReservationClient do
  # "The client converts HTTP answers to `Invoices::ReservationOutcome` itself: a 409 `conflict` maps to refused with conflicts, `unresolved_operation` and `stale_generation` map to retryable, and a timeout or 5xx maps to retryable."
  # The outcome's reason can reach logs and errors, so it must never carry the service token.
  it "reservation client answers a lost transport retryable without the bearer token in its outcome" do
    sent_tokens = []
    http = Object.new
    http.define_singleton_method(:call) do |_method, _path, headers: {}, body: nil|
      sent_tokens << headers.to_h.find { |name, _value| name.to_s.casecmp?("authorization") }&.last.to_s
      raise Timekeeping::ReservationClient::TransportError, "Timekeeping prepare failed: Net::ReadTimeout"
    end
    credential = lambda do |company_id:, operation:|
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    client = described_class.new(http:, credential:)
    request = Invoices::ReservationRequest.new(
      company_id: 812, invoice_id: 3, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: []
    )

    outcome = client.prepare(request)

    expect(outcome.state).to eq("retryable")
    expect(sent_tokens).not_to be_empty
    token = sent_tokens.first.delete_prefix("Bearer ")
    expect(token).not_to be_empty
    expect(outcome.reason.to_s).not_to include(token)
    expect(outcome.reason.to_s).not_to include("Bearer")
    expect(outcome.conflicts).to eq([])
  end
end

RSpec.describe Timekeeping::ReservationClient do
  it "prepare for one company addresses only that company's path and token, and refuses another company's entry without reserving it" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    generation = TimekeepingOwnership.current.generation
    fake.generation = generation
    owner_company = fake.add_company
    other_company = fake.add_company
    owner_user = fake.add_user(company_id: owner_company, role: "admin")
    owner_entry = fake.add_entry(company_id: owner_company, user_id: owner_user,
                                 project_id: fake.add_project(company_id: owner_company)).fetch("id")
    minter = lambda do |company_id:, operation:|
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    client = described_class.new(http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil), credential: minter)
    request = Invoices::ReservationRequest.new(
      company_id: other_company, invoice_id: 77, operation_id: SecureRandom.uuid,
      generation:, disposition: "active", entries: [owner_entry]
    )

    outcome = client.prepare(request)

    # "Build the path from the request's stored company_id."
    sent = fake.requests.last
    expect(sent[:path]).to eq("/v1/companies/#{other_company}/reservations/prepare")
    bearer = sent[:headers].fetch("Authorization").delete_prefix("Bearer ")
    expect(Timekeeping::ServiceToken.verify(bearer, public_key: timekeeping_key_pair.public_key).company_id)
      .to eq(other_company)
