    # other company's save reserves nothing on the owner's entry.
    expect(outcome.state).to eq("refused")
    expect(outcome.conflicts).to eq([{ entry_id: owner_entry, reason: "not_found" }])
    expect(fake.entry_locked?(owner_entry)).to be(false)
    expect(fake.reservations_for(owner_entry)).to eq([])
  end
