RSpec.describe Timekeeping::ReservationClient do
  let(:fake) { TimekeepingContract::FakeTimekeeping.new }
  let(:company_id) { 503 }
  let(:generation) { TimekeepingOwnership.current.generation }
  let(:credential) do
    fake.add_service(company_id:, name: "monolith-invoices", operations: %w[prepare commit abort mark_billed])
  end
  # Forwards every request to the fake, so the fake applies it, then loses the
  # answer of the first prepare as a timed-out connection would.
  let(:dropping_http) do
    Class.new do
      def initialize(inner)
        @inner = inner
        @dropped = false
      end

      def call(method, path, headers: {}, body: nil)
        answer = @inner.call(method, path, headers:, body:)
        if !@dropped && path.end_with?("/reservations/prepare")
          @dropped = true
          raise Timekeeping::ReservationClient::TransportError, "answer dropped"
        end
        answer
      end
    end.new(TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil))
  end
  let(:client) { described_class.new(http: dropping_http, credential: ->(company_id:, operation:) { credential }) }

  # "the fake applies prepare but the answer is dropped: the save fails, and after abort each entry's reservation state equals its state before the save"
  # "Abort delivery first replays the identical prepare (same operation_id and body), then aborts."
  it "an abort after a dropped prepare answer replays the identical prepare and restores every entry's reservations" do
    fake.generation = generation
    free_id = fake.add_entry(company_id:, user_id: 1, project_id: 2).fetch("id")
    held_id = fake.add_entry(company_id:, user_id: 1, project_id: 2).fetch("id")
    fake.add_reservation(entry_id: held_id, invoice_id: 79, state: "committed", disposition: "active")
    before = { free_id => fake.reservations_for(free_id), held_id => fake.reservations_for(held_id) }
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 79, operation_id: SecureRandom.uuid, generation:, disposition: "active",
      entries: [free_id, held_id]
    )

    expect(client.prepare(request).state).to eq("retryable")
    expect(fake.reservations_for(free_id)).to eq([{ "invoice_id" => 79, "state" => "provisional" }])

    expect(client.abort(request).state).to eq("aborted")

    expect({ free_id => fake.reservations_for(free_id), held_id => fake.reservations_for(held_id) }).to eq(before)
    expect(fake.entry_locked?(free_id)).to be(false)
    expect(fake.entry_locked?(held_id)).to be(true)
    paths = fake.requests.map { |call| call[:path].split("/").last }
    expect(paths.first(3)).to eq(%w[prepare prepare abort])
    prepare_bodies = fake.requests.filter_map { |call| call[:body] if call[:path].end_with?("/prepare") }
    expect(prepare_bodies.uniq.size).to eq(1)
  end
end

