      http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil),
      credential: ->(company_id:, operation:) { credential }
    )
  end

  # "a 409 `conflict` maps to refused with conflicts, `unresolved_operation` and `stale_generation` map to retryable, and a timeout or 5xx maps to retryable"
  it "maps a 409 conflict to refused with the conflict reasons kept and a stale generation to retryable" do
    fake.generation = generation
    entry_id = fake.add_entry(company_id:, user_id: 1, project_id: 2).fetch("id")
    fake.add_reservation(entry_id:, invoice_id: 90, state: "committed", disposition: "active")
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 91, operation_id: SecureRandom.uuid, generation:, disposition: "active", entries: [entry_id]
    )

    refused = client.prepare(request)

    expect(refused.state).to eq("refused")
    expect(refused.conflicts).to eq([{ entry_id:, reason: "on_another_invoice" }])

    fake.generation = generation + 1
    stale = client.prepare(
      Invoices::ReservationRequest.new(
        company_id:, invoice_id: 92, operation_id: SecureRandom.uuid, generation:, disposition: "active", entries: [entry_id]
      )
    )

    expect(stale.state).to eq("retryable")
    expect(stale.reason).to eq("stale_generation")
    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => 90, "state" => "committed" }])
  end
end

