RSpec.describe Timekeeping::ReservationClient, "saves through the built client", committed_data: true do
  # "With the owner set to timekeeping, invoice saves that change an entry set call prepare, commit and abort on the fake through Timekeeping::ReservationClient, with no Net::HTTP call in specs"
  it "under the Timekeeping owner invoice saves call prepare, commit and abort on the fake through the built reservation client" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake_client = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    drop_next_prepare = false
    # Forwards every request to the fake; when asked, lets the fake apply one
    # prepare and then loses its answer, as a timed-out connection would.
    http = Object.new
    http.define_singleton_method(:call) do |method, path, headers: {}, body: nil|
      response = fake_client.call(method, path, headers:, body:)
      if drop_next_prepare && path.end_with?("/reservations/prepare")
        drop_next_prepare = false
        raise Timekeeping::ReservationClient::TransportError, "prepare answer lost"
      end
      response
    end
    credential = lambda do |company_id:, operation:|
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    allow(described_class).to receive(:build).and_return(described_class.new(http:, credential:))

    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    user = create(:user, current_workspace_id: company.id)
    entries = Array.new(2) do
      row = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
      fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id, id: row.id)
      row
    end
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = TimekeepingOwnership.current.generation

    committed = create(:invoice, company:, client:, status: :draft)
    create(:invoice_line_item, invoice: committed, timesheet_entry: entries.first, rate: 100, quantity: 60)

    drop_next_prepare = true
    failed_id = nil
    expect do
      ApplicationRecord.transaction do
        failed = create(:invoice, company:, client:, status: :draft)
        failed_id = failed.id
        create(:invoice_line_item, invoice: failed, timesheet_entry: entries.last, rate: 100, quantity: 60)
      end
    end.to raise_error(Invoices::OperationErrors::Retryable)

    routes = fake.requests.map { |request| request[:path].split("/").last }
    expect(routes).to eq(%w[prepare commit prepare prepare abort])
    expect(fake.reservations_for(entries.first.id)).to eq([{ "invoice_id" => committed.id, "state" => "committed" }])
    expect(fake.reservations_for(entries.last.id)).to eq([])
    expect(fake.entry_locked?(entries.last.id)).to be(false)
    expect(InvoiceOperationIntent.where(company_id: company.id, invoice_id: failed_id).pluck(:state)).to eq(["failed"])
    expect(InvoiceOperationOutboxItem.where(company_id: company.id).where.not(delivered_at: nil).pluck(:kind))
      .to contain_exactly("commit", "abort")
  end
end

RSpec.describe Timekeeping::ReservationClient, "invoices that predate the boundary", committed_data: true do
  # "an existing reservation with no intent: a line is removed from a sent invoice, then an entry is added in a separate transaction, and the old entry stays reserved;"
  it "a sent invoice that predates the boundary keeps a removed line's entry reserved on the fake after a later addition" do
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    http = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    credential = lambda do |company_id:, operation:|
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    allow(described_class).to receive(:build).and_return(described_class.new(http:, credential:))

    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    user = create(:user, current_workspace_id: company.id)
    removed, kept, added = Array.new(3) do
      row = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
      fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id, id: row.id)
      row
    end
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = TimekeepingOwnership.current.generation

    sent = create(:invoice, company:, client:, status: :draft)
    removed_line = create(:invoice_line_item, invoice: sent, timesheet_entry: removed, rate: 100, quantity: 60)
    create(:invoice_line_item, invoice: Invoice.find(sent.id), timesheet_entry: kept, rate: 100, quantity: 60)
    sent.update_columns(status: Invoice.statuses.fetch("sent"))
    # The reservations stay on the fake, but the monolith keeps no record of
    # the operations that made them, as for an invoice saved before the boundary.
    InvoiceEntryHolding.where(company_id: company.id, invoice_id: sent.id).delete_all
    InvoiceOperationOutboxItem.where(company_id: company.id, invoice_id: sent.id).delete_all
    InvoiceOperationIntent.where(company_id: company.id, invoice_id: sent.id).delete_all
    expect(fake.reservations_for(removed.id)).to eq([{ "invoice_id" => sent.id, "state" => "committed" }])

    ApplicationRecord.transaction { InvoiceLineItem.find(removed_line.id).destroy! }
    ApplicationRecord.transaction do
      create(:invoice_line_item, invoice: Invoice.find(sent.id), timesheet_entry: added, rate: 100, quantity: 60)
    end

    expect(fake.entry_locked?(removed.id)).to be(true)
    expect(fake.reservations_for(removed.id)).to eq([{ "invoice_id" => sent.id, "state" => "committed" }])
    expect(fake.reservations_for(kept.id)).to eq([{ "invoice_id" => sent.id, "state" => "committed" }])
  end
end

