RSpec.describe Timekeeping::ReservationClient do
  # "Abort delivery first replays the identical prepare (same operation_id and body), then aborts. A prepare whose answer was lost is then terminal, and a late copy cannot reserve."
  it "abort after a prepare whose answer was lost replays the identical prepare, aborts, and a late copy of that prepare reserves nothing" do
    fake = TimekeepingContract::FakeTimekeeping.new
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    project_id = fake.add_project(company_id:)
    entry_id = fake.add_entry(company_id:, user_id:, project_id:).fetch("id")
    credential = fake.add_service(company_id:, name: "monolith-invoices", operations: %w[prepare commit abort mark_billed])
    http = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    client = described_class.new(http:, credential: ->(company_id:, operation:) { credential })
    operation_id = SecureRandom.uuid
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 10, operation_id:, generation: 1, disposition: "active", entries: [entry_id]
    )
    prepare_path = "/v1/companies/#{company_id}/reservations/prepare"
    prepare_body = {
      "invoice_id" => 10, "operation_id" => operation_id, "generation" => 1,
      "disposition" => "active", "entries" => [entry_id]
    }
    headers = { "Authorization" => "Bearer #{credential}" }

    # The save's prepare reached Timekeeping and was applied, but its answer never came back.
    fake.call("POST", prepare_path, headers:, body: prepare_body)
    expect(fake.entry_locked?(entry_id)).to be(true)

    outcome = client.abort(request)

    expect(outcome.state).to eq("aborted")
    expect(fake.requests.pluck(:path))
      .to eq([prepare_path, prepare_path, "/v1/companies/#{company_id}/reservations/abort"])
    expect(fake.requests[1][:body]).to eq(prepare_body)
    expect(fake.entry_locked?(entry_id)).to be(false)
    expect(fake.reservations_for(entry_id)).to eq([])

    # "A prepare that arrives after its abort reserves nothing"
    late = fake.call("POST", prepare_path, headers:, body: prepare_body)
    expect(late.body["state"]).to eq("aborted")
    expect(fake.entry_locked?(entry_id)).to be(false)
    expect(fake.reservations_for(entry_id)).to eq([])
  end
end

RSpec.describe Timekeeping::ReservationClient do
