RSpec.describe Timekeeping::ReservationClient do
  # "A prepare whose answer was lost is then terminal, and a late copy cannot reserve."
  # A conflict on the replay stores no operation on Timekeeping, so nothing is terminal yet:
  # closing the row here would let a prepare still in transit reserve with no abort left to drop it.
  it "abort whose prepare replay is refused with a conflict stays retryable and sends no abort, so a delayed prepare can still be aborted later" do
    fake = TimekeepingContract::FakeTimekeeping.new
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    project_id = fake.add_project(company_id:)
    entry_id = fake.add_entry(company_id:, user_id:, project_id:).fetch("id")
    fake.add_reservation(entry_id:, invoice_id: 99, state: "committed", disposition: "active")
    credential = fake.add_service(company_id:, name: "monolith-invoices", operations: %w[prepare commit abort mark_billed])
    http = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    client = described_class.new(http:, credential: ->(company_id:, operation:) { credential })
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 10, operation_id: SecureRandom.uuid, generation: 1, disposition: "active", entries: [entry_id]
    )

    outcome = client.abort(request)

    expect(outcome.state).to eq("retryable")
    expect(fake.requests.pluck(:path))
      .not_to include("/v1/companies/#{company_id}/reservations/abort")
    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => 99, "state" => "committed" }])
  end
end

RSpec.describe Timekeeping::ReservationClient, "answer mapping and local claims" do
  # Answers every call with the next scripted [status, body] pair and records
  # the paths it was sent.
  let(:scripted_http_class) do
    Class.new do
      attr_reader :paths

      def initialize(answers)
        @answers = answers
        @paths = []
      end

      def call(_method, path, headers: {}, body: nil)
        @paths << path
        status, answer = @answers.shift
        TimekeepingContract::Response.new(status:, body: answer)
      end
    end
  end
  let(:reservation_request) do
    Invoices::ReservationRequest.new(
      company_id: 611, invoice_id: 12, operation_id: SecureRandom.uuid,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [4001]
    )
  end

  def scripted_reservation_client(http)
    described_class.new(http:, credential: ->(company_id:, operation:) { "service-#{company_id}-#{operation}" })
  end

  it "answers committed with no prepare replay when the commit reports non-zero counts" do
    http = scripted_http_class.new([[200, { "reserved" => 1, "released" => 0 }]])

    outcome = scripted_reservation_client(http).commit(reservation_request)

    expect(outcome.state).to eq("committed")
    expect(outcome.counts).to eq(reserved: 1, released: 0)
    expect(http.paths).to eq(["/v1/companies/611/reservations/commit"])
  end

  it "maps unresolved_operation, a 5xx, a 401, a 404 and malformed 200 bodies to retryable" do
    answers = {
      [409, { "reason" => "unresolved_operation", "operation_id" => "x", "retryable" => true }] => "unresolved_operation",
      [503, nil] => "unavailable",
      [401, { "reason" => "unauthorized" }] => "unexpected_status_401",
      [404, { "reason" => "not_found" }] => "unexpected_status_404",
      [200, { "operation_id" => "x" }] => "malformed_answer",
      [200, nil] => "malformed_answer"
    }

    answers.each do |answer, reason|
      outcome = scripted_reservation_client(scripted_http_class.new([answer])).commit(reservation_request)

      expect([answer, outcome.state, outcome.reason]).to eq([answer, "retryable", reason])
    end
  end

  it "posts mark_billed to the contract's invoice route and answers committed with the billed count" do
    http = scripted_http_class.new([[200, { "billed" => 2 }]])

    outcome = scripted_reservation_client(http).mark_billed(reservation_request)

    expect(outcome.state).to eq("committed")
    expect(outcome.counts).to eq(billed: 2)
    expect(http.paths).to eq(["/v1/companies/611/invoices/12/mark-billed"])
  end

  it "wraps each Net failure of the production transport in TransportError without the credential" do
    transport = described_class::NetHttpTransport.new(base_url: "http://timekeeping.test")
    [Net::ReadTimeout.new, Net::OpenTimeout.new, Errno::ECONNREFUSED.new, SocketError.new, EOFError.new].each do |failure|
      allow(Net::HTTP).to receive(:start).and_raise(failure)

      expect { transport.call("POST", "/v1/companies/1/reservations/prepare", headers: { "Authorization" => "Bearer secret-token" }, body: {}) }
        .to raise_error(described_class::TransportError) { |error| expect(error.message).not_to include("secret-token") }
    end
  end

  context "when another kept invoice claims the entry", :aggregate_failures do
    let(:company) { create(:company) }
    let(:entry) do
      client = create(:client, company:)
      project = create(:project, client:, billable: true)
      create(:timesheet_entry, user: create(:user, current_workspace_id: company.id), project:, bill_status: "unbilled")
    end
    let(:claimed_request) do
      claimant = create(:invoice, company:, client: create(:client, company:))
      InvoiceEntryHolding.create!(company_id: company.id, invoice_id: claimant.id, entry_ids: [entry.id], disposition: "active")
      Invoices::ReservationRequest.new(
        company_id: company.id, invoice_id: claimant.id + 1000, operation_id: SecureRandom.uuid,
        generation: TimekeepingOwnership.current.generation, disposition: "active", entries: [entry.id]
      )
    end

    it "refuses prepare and admit locally as on another invoice and sends nothing" do
      http = scripted_http_class.new([])
      client = scripted_reservation_client(http)

      expect(client.prepare(claimed_request).conflicts).to eq([{ entry_id: entry.id, reason: "on_another_invoice" }])
      expect(client.admit(claimed_request).state).to eq("refused")
      expect(http.paths).to eq([])
    end
  end

  # The mark_billed route bills the invoice's committed reservations, not the
  # entries sent, so billing is refused when those are not the invoice's lines.
  it "refuses mark_billed and sends nothing when the invoice's holding lists other entries than its lines" do
    InvoiceEntryHolding.create!(company_id: 611, invoice_id: 12, entry_ids: [4000, 4001], disposition: "active")
    http = scripted_http_class.new([[200, { "billed" => 2 }]])

    outcome = scripted_reservation_client(http).mark_billed(reservation_request)

    expect(outcome.state).to eq("refused")
    expect(outcome.conflicts).to eq([{ entry_id: 4000, reason: described_class::BILLING_MISMATCH_REASON }])
    expect(http.paths).to eq([])
  end

  it "posts mark_billed when the invoice's holding lists exactly its lines" do
    InvoiceEntryHolding.create!(company_id: 611, invoice_id: 12, entry_ids: [4001], disposition: "active")
    http = scripted_http_class.new([[200, { "billed" => 1 }]])

    outcome = scripted_reservation_client(http).mark_billed(reservation_request)

    expect(outcome.state).to eq("committed")
    expect(http.paths).to eq(["/v1/companies/611/invoices/12/mark-billed"])
  end

  # Commit and abort answer only counts, so an abort that drops nothing must
  # read the stored state instead of reporting aborted.
  it "reports committed, and delivery keeps the failed intent's abort row, when the operation commits between the replay and the abort" do
    fake = TimekeepingContract::FakeTimekeeping.new
    fake.generation = TimekeepingOwnership.current.generation
    credential = fake.add_service(company_id: 611, name: "monolith-invoices", operations: %w[prepare commit abort mark_billed])
    fake_client = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    fake.add_entry(company_id: 611, user_id: 1, project_id: 1, id: 4001)
    committing_http = Object.new
    committing_http.define_singleton_method(:call) do |method, path, headers: {}, body: nil|
      if path.end_with?("/reservations/abort")
        fake_client.call(method, path.sub("/abort", "/commit"), headers:, body:)
      end
      fake_client.call(method, path, headers:, body:)
    end
    client = described_class.new(http: committing_http, credential: ->(company_id:, operation:) { credential })
    expect(client.prepare(reservation_request).state).to eq("prepared")

    expect(client.abort(reservation_request).state).to eq("committed")
    expect(fake.reservations_for(4001)).to eq([{ "invoice_id" => 12, "state" => "committed" }])

    InvoiceOperationIntent.create!(
      company_id: 611, invoice_id: 12, operation_id: reservation_request.operation_id, state: "failed",
      generation: reservation_request.generation, disposition: "active", desired_entry_ids: [4001]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id: 611, invoice_id: 12, operation_id: reservation_request.operation_id, kind: "abort",
      payload: { company_id: 611, invoice_id: 12, operation_id: reservation_request.operation_id }
    )
    DeliverInvoiceOperationJob.perform_now(row.id, reservations: client)

    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
  end
end
